import React, { useState, useEffect } from "react";
import { Download, Copy, Check, ExternalLink, ShieldCheck } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/components/ui/use-toast";
import { base44 } from "@/api/base44Client";
import { apiClient, API_BASE_URL } from "@/api/client";
import { useAuth } from "@/lib/AuthContext";

// QR codes are generated by OUR OWN backend (not a third-party API), so
// they keep working even if some outside service goes down. Each table
// gets its own QR (so you know which table an order came from), but you
// can also just print/share ONE generic link if you don't need per-table.
export default function AdminQR() {
  const { user } = useAuth();
  const [restaurant, setRestaurant] = useState(null);
  const [tableCount, setTableCount] = useState(10);
  const [generating, setGenerating] = useState(false);
  const [copied, setCopied] = useState(null);
  const { toast } = useToast();

  const loadRestaurant = async () => {
    const list = await base44.entities.Restaurant.list();
    setRestaurant(list[0] || null);
  };

  useEffect(() => { loadRestaurant(); }, []);

  const genericMenuUrl = restaurant ? `${window.location.origin}/menu/${restaurant.slug}` : "";

  const handleGenerate = async () => {
    if (!restaurant) return;
    setGenerating(true);
    try {
      await apiClient.request(`/api/qr/generate/${restaurant.id}`, {
        method: "POST",
        body: { tableCount: parseInt(tableCount) || 1 }
      });
      toast({ title: `${tableCount} QR codes generated!` });
      await loadRestaurant();
    } catch (err) {
      toast({ title: "Error", description: err.message, variant: "destructive" });
    } finally {
      setGenerating(false);
    }
  };

  const handleCopy = (url, key) => {
    navigator.clipboard.writeText(url);
    setCopied(key);
    toast({ title: "Link copied!" });
    setTimeout(() => setCopied(null), 2000);
  };

  const handleDownload = (dataUrl, label) => {
    const a = document.createElement("a");
    a.href = dataUrl;
    const safeName = (restaurant?.name || "menu").toLowerCase().replace(/\s+/g, "-");
    a.download = `${safeName}-${label}-qr.png`;
    a.click();
  };

  if (!restaurant) {
    return <div className="text-stone-400 text-sm">Loading...</div>;
  }

  return (
    <div className="space-y-8 max-w-2xl">
      <div>
        <h1 className="text-2xl font-heading font-bold text-stone-900">QR Codes</h1>
        <p className="text-stone-500 text-sm mt-1">
          Generate printable QR codes for <strong>{restaurant.name}</strong>'s tables — each links straight to your live menu.
        </p>
      </div>

      <div className="flex items-start gap-3 bg-green-50 border border-green-100 rounded-2xl p-4">
        <ShieldCheck size={18} className="text-green-600 flex-shrink-0 mt-0.5" />
        <p className="text-xs text-green-700">
          QR codes only ever link to your public customer menu. The admin dashboard is never reachable from a QR code.
        </p>
      </div>

      {/* Generic link (no table number) */}
      <div className="bg-white rounded-2xl border border-stone-100 p-6 space-y-4">
        <Label className="text-sm font-semibold text-stone-900">Your Menu Link</Label>
        <div className="flex gap-2">
          <Input value={genericMenuUrl} readOnly className="bg-stone-50 text-sm" />
          <Button variant="outline" onClick={() => handleCopy(genericMenuUrl, "generic")} className="flex-shrink-0">
            {copied === "generic" ? <Check size={16} className="text-green-600" /> : <Copy size={16} />}
          </Button>
          <Button variant="outline" asChild className="flex-shrink-0">
            <a href={genericMenuUrl} target="_blank" rel="noopener noreferrer"><ExternalLink size={16} /></a>
          </Button>
        </div>
        {genericMenuUrl.includes("localhost") && (
          <p className="text-xs text-amber-600">⚠️ Running on localhost — this link only works on this computer. Deploy online before printing for real customers.</p>
        )}
      </div>

      {/* Generate per-table QR codes */}
      <div className="bg-white rounded-2xl border border-stone-100 p-6 space-y-4">
        <Label className="text-sm font-semibold text-stone-900">Generate Table QR Codes</Label>
        <div className="flex items-center gap-3">
          <Input type="number" min="1" max="100" value={tableCount} onChange={e => setTableCount(e.target.value)} className="w-24" />
          <span className="text-sm text-stone-500">tables</span>
          <Button onClick={handleGenerate} disabled={generating} className="bg-amber-600 hover:bg-amber-700 ml-auto">
            {generating ? "Generating..." : "Generate"}
          </Button>
        </div>
      </div>

      {/* Generated QR grid */}
      {restaurant.tables?.length > 0 && (
        <div className="bg-white rounded-2xl border border-stone-100 p-6">
          <Label className="text-sm font-semibold text-stone-900 mb-4 block">Table QR Codes ({restaurant.tables.length})</Label>
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-4">
            {restaurant.tables.map(t => (
              <div key={t.tableNumber} className="border border-stone-100 rounded-xl p-3 text-center">
                <img src={t.qrDataUrl} alt={`Table ${t.tableNumber}`} className="w-full rounded-lg mb-2" />
                <p className="text-xs text-stone-500 mb-2">Table {t.tableNumber}</p>
                <Button size="sm" variant="outline" className="w-full text-xs" onClick={() => handleDownload(t.qrDataUrl, `table-${t.tableNumber}`)}>
                  <Download size={12} className="mr-1" /> Download
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
